import{bV as e,aL as l,u as r,G as t}from"./chunks/framework.BfzMay2U.js";const p=JSON.parse('{"title":"LLMOps 项目需求拆分与设计","description":"","frontmatter":{"title":"LLMOps 项目需求拆分与设计","date":"2026-10-18T15:16:11.000Z"},"headers":[],"relativePath":"ai/llmops.md","filePath":"ai/llmops.md"}'),i={name:"ai/llmops.md"};function o(h,a,n,d,s,c){return l(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="llmops-项目需求拆分与设计" tabindex="-1">LLMOps 项目需求拆分与设计 <a class="header-anchor" href="#llmops-项目需求拆分与设计" aria-label="Permalink to &quot;LLMOps 项目需求拆分与设计&quot;">​</a></h1><h2 id="_1-应用模块" tabindex="-1">1. 应用模块 <a class="header-anchor" href="#_1-应用模块" aria-label="Permalink to &quot;1. 应用模块&quot;">​</a></h2><h3 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h3><p>LLMOps 的核心配置在于通过不同的<code>Prompt</code>来让 LLM 实现不同的功能,应用模块中添加的提示词均为系统提示词</p><h3 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h3><ul><li>短期记忆: 在不超过上下文的情况下固定携带最近的 N 条消息作为短期记忆</li><li>长期记忆: 长期记忆总结整个对话流程,用一段不超过固定长度的话来总结整个对话</li></ul><h3 id="技能" tabindex="-1">技能 <a class="header-anchor" href="#技能" aria-label="Permalink to &quot;技能&quot;">​</a></h3><ul><li>工具</li><li>工作流</li></ul><p>关联工具或者工作流,在 LLM 需要调用技能才能实现时,会自动调用对应的技能</p><h3 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h3><p>应用可以关联多个知识库,如果关联了知识库,应用会在每次对话的时候,先查询知识库,然后将知识库检索的文档片段一起附加到提示中一起提问.</p><h3 id="开场白" tabindex="-1">开场白 <a class="header-anchor" href="#开场白" aria-label="Permalink to &quot;开场白&quot;">​</a></h3><p>用户进入应用后自动展示的引导信息,它的主要目的是帮助用户理解应用的用途,以及如何与其交互</p><h3 id="追问" tabindex="-1">追问 <a class="header-anchor" href="#追问" aria-label="Permalink to &quot;追问&quot;">​</a></h3><ul><li>在每次生成回复后,大语言模型生成对应的后续的问题建议,给用户后续二次提问提供参考</li><li>最多支持设置 5 个用户问题建议</li></ul><h3 id="推荐问题" tabindex="-1">推荐问题 <a class="header-anchor" href="#推荐问题" aria-label="Permalink to &quot;推荐问题&quot;">​</a></h3><p>为应用设置不超过 3 个推荐问题,在应用的对话聊天界面,点击推荐问题可以直接使用推荐问题和应用对话</p><h3 id="语音" tabindex="-1">语音 <a class="header-anchor" href="#语音" aria-label="Permalink to &quot;语音&quot;">​</a></h3><ul><li>语音输入</li><li>语音输出</li></ul><p>语音输出时,支持配置对应的音色,语气风格</p><h3 id="敏感内容审核" tabindex="-1">敏感内容审核 <a class="header-anchor" href="#敏感内容审核" aria-label="Permalink to &quot;敏感内容审核&quot;">​</a></h3><p>对用户输入以及 LLM 的输出进行审核,支持使用敏感关键词</p><h3 id="调试对话" tabindex="-1">调试对话 <a class="header-anchor" href="#调试对话" aria-label="Permalink to &quot;调试对话&quot;">​</a></h3><p>支持在编排界面基于最新的配置信息与应用进行调试对话,校验配置效果,并支持清空对话</p><h2 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h2><h2 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h2><h2 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h2>',27)])])}const b=e(i,[["render",o]]);export{p as __pageData,b as default};
